// COPY-ONLY types for the diagnostic implementation; no production API.
export function diagnosticSync<T>(name:string,work:()=>T):T;
export function diagnosticAsync<T>(name:string,work:()=>Promise<T>):Promise<T>;
export function diagnosticContext<T>(work:()=>Promise<T>):Promise<T>;
export function diagnosticBegin():number;
export function diagnosticEnd(name:string,start:number):void;
export function diagnosticDocument(path:string,bytes:Buffer):void;
export function diagnosticQueued():number;
export function diagnosticReadStart(queued:number):unknown;
export function diagnosticReadEnd(ticket:unknown,bytes?:Buffer,error?:unknown):void;
export function diagnosticMemoFactory(url:string,maxEntries:number,maxBytes:number):number;
export function diagnosticMemoState(id:number,entries:number,accountedBytes:number):void;
export function diagnosticMemoParser(id:number,total:number):void;
export function diagnosticMemoBranch(id:number,branch:string):void;
export function diagnosticMemoBypass(id:number,reason:string):undefined;
export function diagnosticBoundary<T>(req:import('node:http').IncomingMessage,res:import('node:http').ServerResponse,work:()=>T):T;
export function diagnosticLifecycle(event:string,fields:Record<string,unknown>):void;

