export function diagnosticEnd(name,start){const o=owner();if(o&&start){add(o.syncMs,name,now()-start);add(o.calls,name);}}
export function diagnosticBoundary(req,res,work){
 const r={event:'request',id:++state.requests,url:req.url,method:req.method,start:now(),wallStart:Date.now(),syncMs:{},asyncMs:{},calls:{},contextIds:[],memoryStart:memory()},cpu=process.cpuUsage(),elu=performance.eventLoopUtilization();
 state.activeRequests.add(r.id);state.peakRequests=Math.max(state.peakRequests,state.activeRequests.size);write({...r,event:'request-start',active:state.activeRequests.size});res.setHeader('x-spm-diagnostic-request',String(r.id));
 let finished=false;
 const finish=event=>{if(finished)return;finished=true;state.activeRequests.delete(r.id);write({...r,event,end:now(),wallEnd:Date.now(),status:res.statusCode,cpu:process.cpuUsage(cpu),elu:performance.eventLoopUtilization(elu),memoryEnd:memory(),active:state.activeRequests.size,peakGlobalRequests:state.peakRequests,peakGlobalContexts:state.peakContexts});};
 res.once('finish',()=>finish('request-finish'));res.once('close',()=>{write({event:'response-close',id:r.id,at:now(),status:res.statusCode,finished});finish('request-close-before-finish');});
 return state.als.run({request:r},work);
}
export async function diagnosticContext(work){
 const parent=state.als.getStore()??{},c={event:'context',id:++state.contexts,requestId:parent.request?.id??null,start:now(),syncMs:{},asyncMs:{},calls:{},docs:0,bytes:0,collections:{},readCalls:0,readBytes:0,readErrors:0,readActive:0,readPeak:0,queueSumMs:0,queueMaxMs:0,callbackSumMs:0,callbackMaxMs:0,memo:{},memoryStart:memory(),memoStart:summary()},cpu=process.cpuUsage(),elu=performance.eventLoopUtilization();
 parent.request?.contextIds.push(c.id);state.activeContexts.add(c.id);state.peakContexts=Math.max(state.peakContexts,state.activeContexts.size);write({event:'context-start',id:c.id,requestId:c.requestId,start:c.start,active:state.activeContexts.size,memo:c.memoStart});
 return state.als.run({...parent,context:c},async()=>{try{return await work();}catch(error){c.error={name:error?.name,code:error?.code};throw error;}finally{state.activeContexts.delete(c.id);write({...c,end:now(),cpu:process.cpuUsage(cpu),elu:performance.eventLoopUtilization(elu),memoryEnd:memory(),memoEnd:summary(),active:state.activeContexts.size,peakGlobalContexts:state.peakContexts});}});
}
export function diagnosticDocument(path,bytes){const c=state.als.getStore()?.context;if(!c)return;c.docs++;c.bytes+=bytes.length;add(c.collections,/\/(tasks|specs|handoffs|session|org)\//.exec(path)?.[1]??'current');}
export function diagnosticQueued(){return now();}
export function diagnosticReadStart(queued){const c=state.als.getStore()?.context;if(!c)return null;const start=now();c.readCalls++;c.readActive++;c.readPeak=Math.max(c.readPeak,c.readActive);const wait=start-queued;c.queueSumMs+=wait;c.queueMaxMs=Math.max(c.queueMaxMs,wait);return{c,start};}
export function diagnosticReadEnd(ticket,bytes,error){if(!ticket)return;const {c,start}=ticket;c.readActive--;const elapsed=now()-start;c.callbackSumMs+=elapsed;c.callbackMaxMs=Math.max(c.callbackMaxMs,elapsed);if(bytes)c.readBytes+=bytes.length;if(error)c.readErrors++;}
export function diagnosticMemoFactory(url,maxEntries,maxBytes){const id=++state.memos;const value={id,url,maxEntries,maxBytes,entries:0,accountedBytes:0,parserIdentities:0};state.factories.set(id,value);write({event:'memo-factory',...value,at:now()});return id;}
export function diagnosticMemoState(id,entries,accountedBytes){const value=state.factories.get(id);value.entries=entries;value.accountedBytes=accountedBytes;}
function memoAggregate(id){const o=owner();if(!o)return null;o.memo??={};return o.memo[id]??=( {hits:0,misses:0,missAbsent:0,missChanged:0,bypasses:0,bypassReasons:{},evictions:0,newParserIdentities:0} );}
export function diagnosticMemoParser(id,total){state.factories.get(id).parserIdentities=total;const m=memoAggregate(id);if(m)m.newParserIdentities++;}
export function diagnosticMemoBranch(id,branch){const m=memoAggregate(id);if(!m)return;if(branch==='hit')m.hits++;else if(branch==='evict')m.evictions++;else{m.misses++;if(branch==='changed')m.missChanged++;else m.missAbsent++;}}
export function diagnosticMemoBypass(id,reason){const m=memoAggregate(id);if(m){m.bypasses++;add(m.bypassReasons,reason);}return undefined;}
export function diagnosticLifecycle(event,fields){write({event,...fields,at:now()});}

